# key: (层, 屏名, 说明)。说明是判断，不是文案，所以手写。
META = {
'sos':      (0,'什么时候必须去医院','这一屏<b>保留否定式</b>——否定的是此刻的手部动作，紧跟身体理由。「吐血」加了精度：血丝或咖啡色。<b>电解质那段警告从吐过那屏移到了这里</b>，因为它真正的意思是「别在家扛」。'),
'home_day': (1,'首页 · 白天','「你来了」不在首页——不预设你是为暴食来的。默认排序：滋味 → 今天怎么样 → 那场 → 我现在不太好。<b>「情绪瓶子」入口按批注挪到「记一个词」下方。</b>最下面是层 4，字最小。'),
'home_risk':(1,'首页 · 风险时段','<b>版式只有一套</b>，只把正念那条提到第一位。滋味只留标题＋「明早再看」——拿掉感官细节，线索就不成立。腾出的位置给一口水。'),
'home_night':(1,'首页 · 22:00–07:00','「今天怎么样」<b>整块不显示</b>——夜里看到空格只会变成一个不吃的理由。她自己写的那句直接显示，不做入口：多一次点击就多一次放弃的机会。'),
'mine':     (1,'我现在不太好 · 分岔','三个急性期入口<b>收成一个</b>。她的原话：「不想一上来就『你来啦』然后选暴没暴食」。这句话不预设是暴食，限制型／回避型／夜食的人都能说，第四支给全类别留口。'),
'during':   (1,'正在吃','水肿那句<b>先说现象再说它是水</b>，顺序反过来才看得懂。人数在这里出现第二次——共通人性的非语言版本。'),
'urge':     (1,'很想吃','「有时候不是」→<b>「有时候是别的」</b>。按钮用的是她自己的口气，那和产品说的话是两回事，所以「什么都不想回答」留着否定式。'),
'empty':    (1,'饿了','<b>这一轮最大的结构改动：从派活改成先问再给。</b>标题「身体空了」→「饿了」，删掉「越压后面越饿」和餐盘结构三行，改成「想吃点什么样的？」五支。<b>这反而命中了语气原则第一条：第一句话不得是指令。</b>粒子水墨潮汐加在这里——产品的中心隐喻，也是名字的来源；不出现倒计时数字，看着秒数走本身会制造焦虑。'),
'eat_热乎乎的':(1,'饿了 · 热乎乎的','五支各不同，但<b>每支都凑齐主食、一样蛋白质、正常的油</b>。屏上一个数字都不出现。'),
'eat_冰冰凉的':(1,'饿了 · 冰冰凉的','冷的那一支同样要有蛋白质和碳水——奶、酸奶、坚果都算。'),
'eat_软的、好咽的':(1,'饿了 · 软的、好咽的','这一支和吐过之后那屏的建议是同一套：温、软、好咽。'),
'eat_有嚼头的':(1,'饿了 · 有嚼头的','「菜照常炒，油照常放」留在这一支里——「照常」只是照旧，「正常」会暗示存在一个不正常。'),
'eat_说不上来':(1,'饿了 · 说不上来','<b>原来那份餐盘结构没浪费</b>，成了这一支的兜底。说不上来想吃什么本身很常见，不该是死路。'),
'skill':    (1,'冲动那一阵','这一页<b>不计时</b>——线索驱动的渴望不会快速消退，给一个时长范围是错的。抵消那句用不点名的版本，一句挡三样。一口水在这里作备选并<b>跳过感官步</b>：感官聚焦在冲动峰值上会放大对口腔刺激的渴望。'),
'quiet':    (1,'吃不下 · 说不上来','原来只有「这一页就停着」，是个死胡同。<b>按批注改成「愿意做点其他的什么吗」并接到正念</b>——给一条出口，但不催。'),
'passed':   (1,'这阵过去了','「它每次都会退，这次也退了」<b>按批注换成「慢慢平稳一下心情」</b>。原来第三句是第一句的复述，「每次」里已经装着「下次」，早就删了。'),
'after':    (1,'吃完了 · 分岔','<b>她判定原句是反向暗示，对。</b>原句点名了吐、泻药、不吃下一顿。改成<b>只问身体</b>——分诊照做，一个行为名都不出现；「抵消」那一句挡的还是同样三样。'),
'vom':      (1,'吐过之后','<b>主体换成下一顿吃什么</b>（她：「我用你说这个？」）。温、软、好咽是因为黏膜刚受了刺激；一次少一点、隔一会儿再吃是因为胃刚被折腾过。漱口那条已更正：<b>清水或含氟漱口水</b>，不是小苏打——小苏打中和酸有其理，但查不到任何 ED 患者教育指引这么写。'),
'swell':    (1,'停下来的头几天','<b>她这一版比我的准。</b>「可能体重秤上的数字不太好看，镜子里的自己也会有点不同，那是水分」——先说她会看到什么，再说那是水，正是定过的顺序。1 g 糖原结合 3.21±0.57 g 水。这一屏是清除者复发最大的引信。'),
'gate':     (1,'下一餐的闸门','「有一种情况不能在这里写」→<b>「有一种情况要先看化验单」</b>。同一招：说有什么。三个选项都跳到化验单那屏。'),
'med':      (1,'先看化验单','「这跟意志没关系」→<b>「这是身体的反应」</b>。「不在这里写」→「医生看过化验单再定」。就诊话术加了维生素B1（硫胺素）。'),
'three':    (1,'三件误读','删掉三处「其实不是」「不是还没吃够」。<b>这一屏必须点名那三个念头</b>——她正在想那三件事，不点名就没法拆。<b>点名她已有的念头 ≠ 造出她没有的。</b>'),
'sip':      (1,'一口水','<b>她自己的方法。</b>Esplen 1998（n=50 贪食症）六周引导想象：暴食降 74%、呕吐降 73%。用水不用食物是她自己的改编，检索里没见别人写出来。<b>只给结构，不指定意象。</b>按钮名按批注改成「试试含一口水，慢慢感受」——原来那三个字用户看不懂。'),
'siped':    (1,'一口水 · 存好了','第一次建立意象后存本机，之后每次直接调用——<b>把六周疗程压成一个可复用的按钮</b>。'),
'clock':    (2,'今天怎么样','「按钟吃，不按饿吃」→<b>「到点了就吃点东西叭」＋「饿不饿都可以吃一点点」</b>。空格子那句<b>整句删掉</b>——给空格子配任何说明都是把它推到聚光灯下，说「是失分」和「不是失分」一样糟。'),
'feel':     (2,'吃了','「要不要留一个词。不留也行。」→「一个词就够。」不留的许可交给结构。'),
'mood':     (2,'记一个词','<b>加了滋味组</b>——原来十六个词全是情绪词，一个滋味词都没有，而这正是滋味层缺的那一半。'),
'logged':   (2,'记下了','高风险词（空／孤单／羞耻／烦／紧张）记下后<b>多一句，把那场摆到手边</b>——依据：负性情绪与内疚在发作前 4 小时上升。<br><b>这一屏有一处张力：</b>「它不代表对你的任何评价」是个否定式，要读懂它，脑子得先把「评价」造出来。无否定版是「记下了。它只是一个词。」——按她的原话先放着，换不换她定。'),
'bottle':   (2,'情绪瓶子','<b>大字说立场，小字说数据。</b>她给的「允许情绪的存在和不同，多样的ta们才构成了真实的你」意思对，但念不出口，而且会挤掉「谁的都是」——那是这一屏唯一的共通人性（羞耻的核心信念是「只有我这么坏」）。改成分层：大字用瓶子里看得见的东西说同一件事（颜色都不一样，都可以在这儿；合起来才是你），那句数据观察降成小字。<br>原名月度情绪记录。<b>入口按批注挪到首页「记一个词」下方。</b>球是柔边荧光（球体自发光两层，去掉硬高光），二十四个词等饱和等明度、只转色相——<b>如果高兴是亮黄、羞耻是暗灰，这个瓶子就成了记分板</b>。瓶子上<b>不写数量</b>，写了就成了计次。<br>原 s-look 那句「谁的都是」并进了这一页，<b>不另开屏</b>——同一批数据不该有两个视图。'),
'sleep':    (2,'昨晚睡得怎么样','「这跟自控力无关」→改成有出处的说法，并且<b>说人话</b>：抑制控制这个词不上屏。证据强度只到横断面关联加一项实验，所以话要说得轻。'),
'group':    (3,'一起正念','「今天三场」→<b>「一起正念」</b>，上方加正念与冥想两个入口。时间按 EMA 峰值<b>前移</b>（原 17:50/21:30/23:30 全部追在峰值之后）。四个「没有」→一句「屏幕上只有一个数字」。周末减为两场。'),
'mind':     (3,'正念课程','<b>新增。</b>原来播放器下面还有一个「开始」按钮，和播放键重复——<b>删掉按钮，播放器本身就是开始</b>，点了会走进度。右上角同时在线人数。铁规则：不说话、不显示别人、结束不评分。<b>身体扫描走到躯干只说「胸口在动」</b>，不说腰腹腿——那是这个人群最容易被拉进去的地方。'),
'medit':    (3,'冥想课程','<b>新增。</b>夜里那场<b>不做正念</b>——急性期解离已高，注意力不可用，失败会转成羞耻。所以夜里只做渐进放松和接地。'),
'letter':   (4,'留一句给夜里','「这个产品不认识你，也不该假装认识」→<b>「这里只有你自己写的话。」</b>短得多，而且说的是有什么。夜里那句<b>直接显示，不做入口</b>。'),
'fit':      (4,'答两个问题','她的批注是「没懂这是干啥的」——<b>含糊的原因是没说清到底改什么</b>。原来只写「有两件事会改变这里给你什么」。现在每一问下面直接写它会带来哪两屏：答「有」清除行为→多出吐过之后与停下来的头几天（<b>后者最要紧，停下来会肿最容易被读成胖</b>）；答「有」长期少吃→下一餐先看化验单（<b>很久吃得很少之后突然大量进食，磷钾镁会掉得很快</b>）。'),
'help':     (4,'如果愿意，可以找人帮忙','<b>替代原来的「给医生的一页」。</b>批注要求放具体的医生／咨询师／营养师的个人信息与联系方式，<b>这条没做</b>：要爬真实从业者的可识别信息，涉及未经本人同意的收集与展示；把他们放进产品等于代表他们做转诊承诺，而不做清单里写着不替代治疗。<br>换成机构入口＋<b>怎么判断这个人合不合适</b>四条。<b>后面这半是她的专业判断，市面上没人写</b>，比一份名单更有用也更站得住。要放具体的人，得是本人授权的合作名单——那是上线前的合规工作，路演里可以当 roadmap 讲。'),
'notyet':   (4,'还没打算改变','「好。那就不改」→「好。那就这样。」正文按批注换成<b>「改变会发生在你想改变的时候」</b>——这是她亲历输入第一条的原话。<b>不做第三个选项</b>，放在「为自己来的」之后一行小字。'),
'entry':    (9,'进来时那一问','<b>两类人都不起名，用处境。</b>不要求任何人承认有病。分流之后两端硬隔离、互不可见；切回口藏在层 4 最后一行。'),
'worry':    (9,'我在担心一个人','「你不用先确定是不是真的」→<b>「先进来看看。」</b>照护者端的「不是」大多可以留——那里否定的是<b>他的误读</b>，不是她的自我判断。读的人是他，被松开的是她。'),
'two':      (9,'两个相反的方向','<b>「不敢说」那一支还没写</b>——现在七张卡治的是「忍不住说」，对不敢说的人「先别开口」反而是加码。这是整套文案最大的一个洞。'),
'tr':       (9,'行为翻译器','七张卡<b>不定义人，只给反应命名</b>，正文见附录 C。动物名放卡片下方、加引号、可点开文献原表。'),
'learn':    (9,'给你看的东西','<b>新增。</b>照护者的困境是不理解，且不在急性期，所以这一端<b>可以放书和课</b>——但一周一条，不做成要读完的库。<b>片单不放</b>：ED 题材影视普遍带具体化描写，既是患者的触发源，也会给照护者种下「必须瘦到那个程度才算严重」的误解。'),
}
